ing";s:3:"URL";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:28:"The URL of the current page.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:3:"url";}s:5:"query";a:3:{s:4:"name";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:18:"Query string value";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:63:"The value of a specific query string field of the current page.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:7:"dynamic";b:1;}}s:7:"metatag";a:89:{s:7:"refresh";a:3:{s:4:"name";s:20:"Avan\\303\\247ado: Atualizar";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:190:"The number of seconds to wait before refreshing the page. May also force redirect to another page using the format '5; url=https://example.com/', which would be triggered after five seconds.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:15:"metatag-refresh";}s:6:"author";a:3:{s:4:"name";s:16:"Avan\\303\\247ado: Autor";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:28:"Define the author of a page.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:14:"metatag-author";}s:6:"rating";a:3:{s:4:"name";s:22:"Avan\\303\\247ado: Avalia\\303\\247\\303\\243o";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:454:"Used to rate content for audience appropriateness. This tag has little known influence on search engine rankings, but can be used by browsers, browser extensions, and apps. The <a href='https://www.metatags.org/meta_name_rating'>most common options</a> are general, mature, restricted, 14 years, safe for kids. If you follow the <a href='https://www.rtalabel.org/index.php?content=howto'>RTA Documentation</a> you should enter RTA-5042-1996-1400-1577-RTA";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:14:"metatag-rating";}s:13:"cache_control";a:3:{s:4:"name";s:24:"Avan\\303\\247ado: Cache control";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:140:"Used to control whether a browser caches a specific page locally. Not commonly used. Should be used in conjunction with the Pragma meta tag.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:21:"metatag-cache_control";}s:7:"expires";a:3:{s:4:"name";s:17:"Avan\\303\\247ado: Expira";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:331:"Control when the browser's internal cache of the current page should expire. The date must to be an <a href='https://www.csgnetwork.com/timerfc1123calc.html'>RFC-1123</a>-compliant date string that is represented in Greenwich Mean Time (GMT), e.g. 'Thu, 01 Sep 2016 00:12:56 GMT'. Set to '0' to stop the page being cached entirely.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:15:"metatag-expires";}s:13:"geo_placename";a:3:{s:4:"name";s:34:"Avan\\303\\247ado: Geographical place name";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:25:"A location's formal name.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:21:"metatag-geo_placename";}s:12:"geo_position";a:3:{s:4:"name";s:32:"Avan\\303\\247ado: Geographical position";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:261:"Geo-spatial information in 'latitude; longitude' format, e.g. '50.167958; -97.133185'; <a href='https://en.wikipedia.org/wiki/Geographic_coordinate_system' aria-label='see Wikipedia for details on the geographic coordinate system'>see Wikipedia for details</a>.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:20:"metatag-geo_position";}s:10:"geo_region";a:3:{s:4:"name";s:30:"Avan\\303\\247ado: Geographical region";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:130:"A location's two-letter international country code, with an optional two-letter region, e.g. 'US-NH' for New Hampshire in the USA.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:18:"metatag-geo_region";}s:9:"generator";a:3:{s:4:"name";s:18:"Avan\\303\\247ado: Gerador";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:97:"Describes the name and version number of the software or publishing tool used to create the page.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:17:"metatag-generator";}s:6:"google";a:3:{s:4:"name";s:17:"Avan\\303\\247ado: Google";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:411:"This meta tag communicates with Google. There are currently two directives supported: 'nositelinkssearchbox' to not to show the sitelinks search box, and 'notranslate' to ask Google not to offer a translation of the page. Both options may be added, just separate them with a comma. See <a href='https://support.google.com/webmasters/answer/79812?hl=en'>meta tags that Google understands</a> for further details.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:14:"metatag-google";}s:4:"icbm";a:3:{s:4:"name";s:15:"Avan\\303\\247ado: ICBM";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:227:"Geo-spatial information in 'latitude, longitude' format, e.g. '50.167958, -97.133185'; <a href='https://en.wikipedia.org/wiki/ICBM_address' aria-label='see Wikipedia for details on ICBM addresses'>see Wikipedia for details</a>.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:12:"metatag-icbm";}s:9:"image_src";a:3:{s:4:"name";s:17:"Avan\\303\\247ado: Imagem";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:97:"An image associated with this page, for use as a thumbnail in social networks and other services.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:17:"metatag-image_src";}s:9:"shortlink";a:3:{s:4:"name";s:25:"Avan\\303\\247ado: Link encurtado";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:55:"A brief URL, often created by a URL shortening service.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:17:"metatag-shortlink";}s:4:"next";a:3:{s:4:"name";s:24:"Avan\\303\\247ado: Next page URL";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:65:"Used for paginated content by providing URL with rel='next' link.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:12:"metatag-next";}s:15:"original_source";a:3:{s:4:"name";s:26:"Avan\\303\\247ado: Original source";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:200:"Used to indicate the URL that broke the story, and can link to either an internal URL or an external source. If the full URL is not known it is acceptable to use a partial URL or just the domain name.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:23:"metatag-original_source";}s:6:"pragma";a:3:{s:4:"name";s:17:"Avan\\303\\247ado: Pragma";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:147:"Used to control whether a browser caches a specific page locally. Not commonly used. Should be used in conjunction with the Cache-Control meta tag.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:14:"metatag-pragma";}s:4:"prev";a:3:{s:4:"name";s:28:"Avan\\303\\247ado: Previous page URL";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:65:"Used for paginated content by providing URL with rel='prev' link.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:12:"metatag-prev";}s:8:"referrer";a:3:{s:4:"name";s:26:"Avan\\303\\247ado: Referrer policy";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:280:"Indicate to search engines and other page scrapers whether or not links should be followed. See <a href='https://w3c.github.io/webappsec/specs/referrer-policy/'>the W3C specifications</a> for further details. Note: this serves the same purpose as the HTTP header by the same name.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:16:"metatag-referrer";}s:13:"revisit_after";a:3:{s:4:"name";s:24:"Avan\\303\\247ado: Revisit After";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:193:"Tell search engines when to index the page again. Very few search engines support this tag, it is more useful to use an <a href='https://www.drupal.org/project/xmlsitemap'>XML Sitemap</a> file.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:21:"metatag-revisit_after";}s:6:"rights";a:3:{s:4:"name";s:17:"Avan\\303\\247ado: Rights";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:145:"Details about intellectual property, such as copyright or trademarks; does not automatically protect the site's content or intellectual property.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:14:"metatag-rights";}s:6:"robots";a:3:{s:4:"name";s:17:"Avan\\303\\247ado: Rob\\303\\264s";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:90:"Provides search engines with specific directions for what to do when this page is indexed.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:14:"metatag-robots";}s:10:"set_cookie";a:3:{s:4:"name";s:21:"Avan\\303\\247ado: Set cookie";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:251:"<a href='https://www.metatags.org/meta_http_equiv_set_cookie'>Sets a cookie</a> on the visitor's browser. Can be in either NAME=VALUE format, or a more verbose format including the path and expiration date; see the link for full details on the syntax.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:18:"metatag-set_cookie";}s:13:"canonical_url";a:3:{s:4:"name";s:24:"Avan\\303\\247ado: URL can\\303\\264nica";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:140:"A link to the preferred page location or URL of the content of this page, to help eliminate duplicate content penalties from search engines.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:21:"metatag-canonical_url";}s:8:"abstract";a:3:{s:4:"name";s:20:"Basic tags: Abstract";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:341:"A brief and concise summary of the page's content, preferably 150 characters or less. Where as the description meta tag may be used by search engines to display a snippet about the page in search results, the abstract tag may be used to archive a summary about the page. This meta tag is <em>no longer</em> supported by major search engines.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:16:"metatag-abstract";}s:11:"description";a:3:{s:4:"name";s:23:"Basic tags: Descri\\303\\247\\303\\243o";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:206:"A brief and concise summary of the page's content that is a maximum of 160 characters in length. The description meta tag may be used by search engines to display a snippet about the page in search results.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:19:"metatag-description";}s:8:"keywords";a:3:{s:4:"name";s:26:"Basic tags: Palavras-chave";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:120:"A comma-separated list of keywords about the page. This meta tag is <em>no longer</em> supported by most search engines.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:16:"metatag-keywords";}s:5:"title";a:3:{s:4:"name";s:30:"Basic tags: T\\303\\255tulo da p\\303\\241gina";s:11:"description";O:48:"Drupal\\\\Core\\\\StringTranslation\\\\TranslatableMarkup":3:{s:9:"\\000*\\000string";s:437:"The text to display in the title bar of a visitor's web browser when they view this page. This meta tag may also be used as the title of the page when a visitor bookmarks or favorites this page, or as the page title in a search engine result. It is common to append '[site:name]' to the end of this, so the site's name is automatically added. It is recommended that the title is no greater than 55 - 65 characters long, including spaces.";s:12:"\\000*\\000arguments";a:0:{}s:10:"\\000*\\000options";a:0:{}}s:4:"type";s:13:"metatag-title";}s:9:"fb_admins";a:3:{s:4:"name";s:25:"facebook: Facebook Admins";s:11:"description";O:48:"Drupal\